const serviceData = $('Fetch Service Status').first().json || {};
const agentData = $('Fetch Agent Status').all().map(i => i.json);
const heartbeatData = $('Fetch Recent Heartbeats').all().map(i => i.json);
const telemetryData = $('Fetch Workflow Telemetry').all().map(i => i.json);

// --- EXPECTED STATE (update when docs change) ---
const EXPECTED = {
  core_services: [
    'telemetry-api',
    'n8n',
    'postgres',
    'decision-engine',
    'litellm-proxy',
    'redis',
    'guardspine-api',
  ],
  active_agents: [
    'content-scheduler',
    'outreach-sequencer',
    'health-monitor',
    'pipeline-metrics',
    'partner-scanner',
    'performance-tracker'
  ],
  min_active_workflows: 8,
  telemetry_rejects_raw_sql: true,
  kpi_health_has_data: true
};

const drift_items = [];
const now = new Date().toISOString();

// Check 1: Core services
const healthStatus = serviceData.status || serviceData.health || 'unknown';
if (healthStatus !== 'ok' && healthStatus !== 'healthy') {
  drift_items.push({
    category: 'service_health',
    expected: 'ok or healthy',
    actual: healthStatus,
    detail: 'Telemetry API health endpoint returned unexpected status'
  });
}

// Check available routes/services from health response
const reportedServices = serviceData.services || serviceData.routes || [];
if (Array.isArray(reportedServices) && reportedServices.length > 0) {
  for (const svc of EXPECTED.core_services) {
    const found = reportedServices.some(r => {
      const name = (typeof r === 'string') ? r : (r.name || r.service || '');
      return name.toLowerCase().includes(svc.toLowerCase());
    });
    if (!found) {
      drift_items.push({
        category: 'missing_service',
        expected: svc,
        actual: 'not found in health response',
        detail: 'Expected service not reported by health endpoint'
      });
    }
  }
}

// Check 2: Active agents
const actualAgents = agentData.map(a => a.name || a.agent_name || '').filter(Boolean);
for (const expectedAgent of EXPECTED.active_agents) {
  const found = actualAgents.some(a => a.toLowerCase().includes(expectedAgent.toLowerCase()));
  if (!found) {
    drift_items.push({
      category: 'missing_agent',
      expected: expectedAgent,
      actual: 'not found in agent_status query',
      detail: 'Expected agent not returned by agent_status'
    });
  }
}

// Check for unexpected agents (new agents not in docs)
for (const actual of actualAgents) {
  const documented = EXPECTED.active_agents.some(e => actual.toLowerCase().includes(e.toLowerCase()));
  if (!documented) {
    drift_items.push({
      category: 'undocumented_agent',
      expected: 'not in expected list',
      actual: actual,
      detail: 'Agent exists in system but not documented'
    });
  }
}

// Check 3: Heartbeat health
const totalHeartbeats = heartbeatData.reduce((sum, h) => sum + (parseInt(h.cnt || h.count || h.total || 0)), 0);
if (totalHeartbeats === 0) {
  drift_items.push({
    category: 'heartbeat_gap',
    expected: 'heartbeat data for past 24h',
    actual: 'no heartbeat records found',
    detail: 'Zero heartbeats in 24h window suggests agents are not running'
  });
}

// Check for agents with high failure rates
for (const hb of heartbeatData) {
  const name = hb.name || hb.agent_name || 'unknown';
  const failed = parseInt(hb.failed || hb.failure_count || 0);
  const succeeded = parseInt(hb.succeeded || hb.success_count || 0);
  const total = failed + succeeded;
  if (total > 0 && failed / total > 0.5) {
    drift_items.push({
      category: 'agent_degraded',
      expected: 'failure rate < 50%',
      actual: name + ': ' + ((failed / total) * 100).toFixed(0) + '% failures',
      detail: 'Agent heartbeat failure rate exceeds 50%'
    });
  }
}

// Check 4: Recent telemetry for workflow errors
const workflowErrors = telemetryData.filter(t => t.event_type === 'workflow_error');
if (workflowErrors.length > 10) {
  drift_items.push({
    category: 'excessive_errors',
    expected: 'fewer than 10 workflow errors in recent telemetry',
    actual: workflowErrors.length + ' workflow errors found',
    detail: 'High workflow error count may indicate system-doc mismatch'
  });
}

return [{
  json: {
    drift_items: drift_items,
    drift_count: drift_items.length,
    checked_at: now,
    services_checked: EXPECTED.core_services.length,
    agents_checked: EXPECTED.active_agents.length
  }
}];
